import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.BZO4qERu.js";const b=JSON.parse('{"title":"文献计量","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/bibliometrics.md","filePath":"zh/guide/bibliometrics.md","lastUpdated":1792570296000}'),d={name:"zh/guide/bibliometrics.md"};function n(i,t,s,h,l,p){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="文献计量" tabindex="-1">文献计量 <a class="header-anchor" href="#文献计量" aria-label="Permalink to &quot;文献计量&quot;">​</a></h1><p>在顶部的<strong>文献计量</strong>中，分析一次已保存检索的元数据。每份分析拥有独立标题、历史和导出。</p><h2 id="创建分析" tabindex="-1">创建分析 <a class="header-anchor" href="#创建分析" aria-label="Permalink to &quot;创建分析&quot;">​</a></h2><p>选择已完成的检索，或从检索结果进入计量分析。系统保存精简候选元数据的独立快照，删除来源检索不会删除分析。</p><p>分析范围是<strong>实际获取并去重的候选集</strong>，包含已获取的引用扩展候选；不是数据源报告的命中总数、整个研究领域，也不只是最终相关性排序结果。检索仍受预算限制，LLM 仍只评分原来的子集。创建分析不会给全部候选打分，不调用语言模型，也不会自动补抓缺失元数据。</p><p>旧检索若没有候选集文件，只能使用其已保存的最终结果，界面会明确标记这一降级范围。如需较完整的候选集，需要重新检索。</p><h2 id="子功能" tabindex="-1">子功能 <a class="header-anchor" href="#子功能" aria-label="Permalink to &quot;子功能&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td>概览</td><td>年份、来源期刊/会议、文献类型、作者、机构、国家/地区、被引数据覆盖及评分子集</td></tr><tr><td>关键词</td><td>原生关键词或来源分类、词频，以及按需生成的共现网络</td></tr><tr><td>文献关系</td><td>文献耦合：用共同的已返回参考文献连接论文</td></tr><tr><td>数据质量</td><td>字段覆盖率、缺失值、分析范围及来源限制</td></tr></tbody></table><p>缺失被引数保留为未知，明确返回的零才计为零。作者和机构仅按返回名称整理，未做实体消歧。国家/地区来自机构信息，不表示作者国籍。关键词会标明来源；OpenAlex 概念、Semantic Scholar 学科分类不能直接等同于作者关键词。</p><h2 id="生成网络" tabindex="-1">生成网络 <a class="header-anchor" href="#生成网络" aria-label="Permalink to &quot;生成网络&quot;">​</a></h2><p>打开网络子页不会自动计算。调整阈值后点击<strong>生成网络</strong>；参数区在提交后收起，可在画布上方重新展开。通过节点搜索、节点详情和分组图例探索网络。服务端按参数缓存已完成结果，图形布局由浏览器 worker 处理；布局失败时可重试。</p><p>共现表示词语在同一篇文献中出现；文献耦合表示论文拥有共同参考文献。分组使用连通分量，不代表经过验证的语义主题。两种关系都不能证明论文支持某个写作结论；这类核对请使用综述中的<strong>引用证据</strong>。</p><p>单图最多显示 <strong>300 个节点、2,000 条边</strong>。稀疏计算还限制候选配对工作量；过密语料需要提高阈值或排除极高频参考文献。界面会提示显示截断和省略情况。分类统计最多保留 100 类，导出保留底层精简候选集。</p><h2 id="历史与导出" tabindex="-1">历史与导出 <a class="header-anchor" href="#历史与导出" aria-label="Permalink to &quot;历史与导出&quot;">​</a></h2><p>在左侧栏选择<strong>文献计量</strong>后，<strong>分析记录</strong>区域显示该模块的记录。点击记录重新打开，点击标题旁的放大镜搜索，或点击<strong>全部</strong>打开完整列表。列表中每行的记录菜单提供重命名、导出和删除。重命名只改显示标题，不改来源检索问题。</p><p>CSV 按文献逐行导出，JSON 同时提供候选集与范围信息；两者与只包含最终结果的检索导出不同。删除分析会清理其快照和网络缓存，保留来源检索及综述。</p><h2 id="解读边界" tabindex="-1">解读边界 <a class="header-anchor" href="#解读边界" aria-label="Permalink to &quot;解读边界&quot;">​</a></h2><p>这是针对单次有限检索的初步文献计量。数据源覆盖、参考文献缺失、名称变体和检索式选择会影响分布与网络，不能替代可复现的多数据库系统检索或专门的计量验证。</p>',18)])])}const _=a(d,[["render",n]]);export{b as __pageData,_ as default};
